class Solution {
    public static List<Object> solve(Map<String, Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        List<List<Object>> operations = (List<List<Object>>) data.get("operations");
        List<Object> result = new ArrayList<>();

        int[] prefixSum = new int[nums.size() + 1];
        for (int i = 0; i < nums.size(); i++) {
            prefixSum[i + 1] = prefixSum[i] + nums.get(i);
        }

        for (List<Object> operation : operations) {
            String type = (String) operation.get(0);
            int l = ((Number) operation.get(1)).intValue();
            int r = ((Number) operation.get(2)).intValue();

            if ("add".equals(type)) {
                prefixSum[l]++;
                prefixSum[r + 1]--;
            } else if ("sum".equals(type)) {
                result.add(prefixSum[r + 1] - prefixSum[l]);
            }
        }

        return result;
    }
}

