class Solution {
    public static List<Integer> solve(Map<String, Object> data) {
        int[] nums = ((List<Integer>) data.get("nums")).stream().mapToInt(Integer::intValue).toArray();
        List<Integer> operations = (List<List<Object>>) data.get("operations");
        List<Integer> result = new ArrayList<>();

        for (List<Object> operation : operations) {
            String opType = (String) operation.get(0);
            int l = (int) operation.get(1);
            int r = (int) operation.get(2);
            int v = (Integer) operation.get(3);

            if ("add".equals(opType)) {
                nums[l] += v;
                nums[r + 1]--;
            } else if ("sum".equals(opType)) {
                int sum = 0;
                for (int i = l; i <= r; i++) {
                    sum += nums[i];
                }
                result.add(sum);
            }
        }

        return result;
    }
}

